function art(item,kind='playlist'){const images=item.artworks?.length?item.artworks:item.artwork?[item.artwork]:[];if(images.length){return '<div class="photo-cover '+(item.channel_logo?'channel-logo':'')+'">'+images.slice(0,1).map(url=>'<img src="'+esc(url)+'" loading="lazy" alt="">').join('')+'</div>'}return '<div class="collection-art quiet-placeholder"><span class="art-label">Arrify</span><strong>'+esc(item.name)+'</strong><small>'+((item.tracks||0)?item.tracks+(item.tracks===1?' song':' songs'):'No songs yet')+'</small></div>'}
function cards(items,kind){return '<div class="card-grid">'+items.map(x=>{const url=kind==='collection'?'collection/'+x.slug:kind+'/'+x.id;const subtitle=x.artist||(x.tracks===0?'No local songs yet':(x.tracks||0)+(x.tracks===1?' song':' songs'));return '<article class="card" tabindex="0" role="link" data-go="'+esc(url)+'" data-search-label="'+esc(x.name)+'"><div class="art-wrap">'+art(x,kind)+'<button class="quick-play" aria-label="Play '+esc(x.name)+'" data-quick="'+esc(url)+'" '+(x.tracks===0?'disabled':'')+'>▶</button></div><h3>'+esc(x.name)+'</h3><p>'+esc(subtitle)+'</p></article>'}).join('')+'</div>'}
function section(title,body,url,description=''){return `<section class="section"><div class="section-head"><h2>${esc(title)}</h2>${url?`<a href="#${url}">View all ↗</a>`:''}</div>${description?`<p class="section-description">${esc(description)}</p>`:''}${body}</section>`}
const stationCardDetails=new Map();
function stations(items){for(const x of items)stationCardDetails.set(x.slug,x);return '<div class="channel-grid">'+items.map(x=>'<article class="station" aria-label="'+esc(x.name)+'" '+(x.tracks?'tabindex="0" role="link" data-go="collection/'+esc(x.slug)+'"':'')+'><div class="station-cover">'+art(x,'collection')+'<button data-tune="'+esc(x.slug)+'" aria-label="Tune '+esc(x.name)+'" '+(!x.tracks?'disabled':'')+'>▶</button><button class="station-details-button" type="button" data-station-details="'+esc(x.slug)+'" aria-label="Information about '+esc(x.name)+'" aria-haspopup="dialog"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6"/><circle cx="12" cy="7" r=".8" fill="currentColor" stroke="none"/></svg></button></div></article>').join('')+'</div>'}
function openStationDetails(slug){
 const item=stationCardDetails.get(slug);if(!item)return;
 const progress=item.station_progress||stationPreferences?.progress?.find(x=>x.slug===slug),counts=progress?.counts;
 let dialog=$('#station-details-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='station-details-dialog';dialog.setAttribute('aria-labelledby','station-details-title');document.body.append(dialog)}
 const trigger=document.activeElement;
 const rows=[['Available to play',item.tracks||0],...(counts?[['Awaiting verification',counts.awaiting_verification],['Verified',counts.verified],['Acquisition queued',counts.queued],['Downloaded, awaiting library availability',counts.downloaded],['Waiting or needs review',counts.waiting]]:[])];
 dialog.innerHTML='<form method="dialog"><button class="dialog-close" aria-label="Close station information">×</button></form><h2 id="station-details-title">'+esc(item.name.replace('SiriusXM ',''))+'</h2><dl>'+rows.map(([label,value])=>'<div><dt>'+esc(label)+'</dt><dd>'+Number(value||0).toLocaleString()+'</dd></div>').join('')+'</dl><p class="muted">'+(progress?.pending?'Waiting for the helper’s first refresh.':progress?.updated?'Helper updated '+esc(new Date(progress.updated).toLocaleString()):'Helper progress has not been reported yet.')+'</p><p class="muted">Songs play from our local library. Queued means acquisition has been requested, not that a download has started.</p>';
 dialog.onclose=()=>{if(trigger?.isConnected)trigger.focus({preventScroll:true})};dialog.showModal();
}
