let stationPreferences=null,editingStations=false,stationSaving=false;
function stationManager(){
 const prefs=stationPreferences;if(!prefs)return '';
 const collections=new Map((home?.collections||[]).map(x=>[x.slug,x]));for(const progress of prefs.progress||[]){const item=collections.get(progress.slug);if(item)collections.set(progress.slug,{...item,station_progress:progress})}
 return `<div class="station-toolbar"><div><h1 class="page-title">Your stations</h1><p class="muted">Your lineup, your order.</p></div></div><p id="station-feedback" class="station-feedback" role="status" aria-live="polite"></p>`+(editingStations?`<p class="muted">Move stations into your preferred order. Turn off Show to hide one.</p><div class="station-edit-list">${prefs.items.map((x,i)=>`<div class="station-edit-row" data-station-row="${esc(x.slug)}"><button class="station-drag icon-button" data-station-drag="${esc(x.slug)}" aria-label="Drag ${esc(x.name)} to reorder" ${stationSaving?'disabled':''}>☰</button><strong>${esc(x.name)}</strong><label class="station-show"><input type="checkbox" data-station-action="hide" data-station-slug="${esc(x.slug)}" ${x.hidden?'':'checked'} ${stationSaving?'disabled':''}>Show</label><div class="station-move"><button class="icon-button" data-station-action="move" data-station-direction="-1" data-station-slug="${esc(x.slug)}" aria-label="Move ${esc(x.name)} up" ${i===0||stationSaving?'disabled':''}>↑</button><button class="icon-button" data-station-action="move" data-station-direction="1" data-station-slug="${esc(x.slug)}" aria-label="Move ${esc(x.name)} down" ${i===prefs.items.length-1||stationSaving?'disabled':''}>↓</button></div><button class="text-button station-remove" data-station-action="remove" data-station-slug="${esc(x.slug)}" aria-label="Remove ${esc(x.name)} from your stations" ${stationSaving?'disabled':''}>Remove</button></div>`).join('')}</div>`:stations(prefs.items.filter(x=>!x.hidden).map(x=>collections.get(x.slug)||{...x,tracks:0,preparing:true,artworks:[]})))+(!prefs.items.length?'<div class="empty-state"><h2>Make yourself at home.</h2><p>Add a station to start your lineup.</p><button class="primary" data-station-add>Add station</button></div>':!editingStations&&prefs.items.every(x=>x.hidden)?'<p class="muted">All your stations are hidden. Choose Edit to show them again.</p>':'')+`<div class="station-toolbar-actions"><button class="chip" data-station-edit aria-pressed="${editingStations}">${editingStations?'Done':'Edit'}</button><button class="primary" data-station-add>＋ Add station</button></div>`+'<p class="channel-credit"><a href="https://xmplaylist.com" target="_blank" rel="noopener noreferrer"><img src="/assets/channels/xmplaylist.ico" width="18" height="18" alt="">Powered by xmplaylist</a><button class="text-button" data-station-info aria-label="About stations">ⓘ</button></p>';
}
