function stationCatalogRows(){
 const d=$('#station-picker');if(!d||!d.querySelector('input'))return;
 const query=d.querySelector('input').value.trim().toLocaleLowerCase(),genre=d.querySelector('select').value;
 const rows=(stationPreferences?.catalog||[]).filter(x=>(!genre||x.genres.includes(genre))&&[x.name,x.number,...x.genres].join(' ').toLocaleLowerCase().includes(query));
 d.querySelector('.station-catalog').innerHTML=rows.map(x=>{const added=stationPreferences.items.some(i=>i.slug===x.slug&&!i.hidden);return `<div class="station-catalog-row"><div><strong>${esc(x.name)}</strong><small>${esc([x.number?'Ch. '+x.number:'',...x.genres].filter(Boolean).join(' · '))}</small></div><button class="chip" data-station-action="add" data-station-slug="${esc(x.slug)}" aria-label="${added?'Added':'Add'} ${esc(x.name)}" ${added||stationSaving?'disabled':''}>${added?'Added':'Add'}</button></div>`}).join('')||'<p class="muted">'+(stationPreferences?.catalog_unavailable?'The station directory is temporarily unavailable. Close and reopen this page to retry.':'No matching stations.')+'</p>';
}
function openStationPicker(){
 let d=$('#station-picker');if(!d){d=document.createElement('dialog');d.id='station-picker';d.className='station-picker';d.setAttribute('aria-labelledby','station-picker-title');document.body.append(d)}
 const genres=[...new Set((stationPreferences.catalog||[]).flatMap(x=>x.genres))].sort();
 d.innerHTML='<form method="dialog"><button class="dialog-close" aria-label="Close station directory">×</button></form><h2 id="station-picker-title">Add a station</h2><p class="muted">Stations use songs in our library. Adding one asks the helper to find missing songs.</p><div class="station-catalog-filters"><label><span class="sr-only">Find a station</span><input type="search" placeholder="Station name or channel number" autocomplete="off"></label><label><span class="sr-only">Genre</span><select><option value="">All genres</option>'+genres.map(g=>'<option value="'+esc(g)+'">'+esc(g)+'</option>').join('')+'</select></label></div><p class="station-picker-message" role="status" aria-live="polite"></p><div class="station-catalog"></div>';
 d.querySelector('input').oninput=stationCatalogRows;d.querySelector('select').onchange=stationCatalogRows;stationCatalogRows();d.showModal();
}
async function changeStation(button){
 if(stationSaving)return;stationSaving=true;
 const action=button.dataset.stationAction,slug=button.dataset.stationSlug;
 const data={action,slug,revision:stationPreferences.revision};if(action==='hide')data.hidden=!button.checked;if(action==='move'){if(button.dataset.stationTarget!==undefined)data.target=Number(button.dataset.stationTarget);else data.direction=Number(button.dataset.stationDirection);}
 let message='';const old=stationPreferences;button.disabled=true;button.setAttribute('aria-busy','true');if(action==='add'){button.textContent='Adding…';$('#station-picker input')?.blur();}
 try{const updated=await api('/stations',data);stationPreferences={...old,...updated};home=await api('/home');message=action==='add'?'Station added. The helper will check missing songs.':action==='remove'?'Removed from your stations.':'Stations updated.';}
 catch(error){if(action==='hide')button.checked=data.hidden;message=error.message;toast(error.message);if($('#station-picker .station-picker-message'))$('#station-picker .station-picker-message').textContent=error.message;}
 finally{stationSaving=false;button.disabled=false;button.removeAttribute('aria-busy');paintStations();stationCatalogRows();$('#station-feedback')?.replaceChildren(document.createTextNode(message));$('#station-picker .station-picker-message')?.replaceChildren(document.createTextNode(message));if(action!=='add'){const selector=`[data-station-action="${action}"][data-station-slug="${CSS.escape(slug)}"]`+(action==='move'?`[data-station-direction="${data.direction}"]`:'');const target=$('#station-personal')?.querySelector(selector);if(target&&!target.disabled)target.focus({preventScroll:true});else $('#station-personal [data-station-edit]')?.focus({preventScroll:true})}}
}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-station-edit')){editingStations=!editingStations;paintStations();$('#station-personal [data-station-edit]')?.focus({preventScroll:true})}else if(b.hasAttribute('data-station-add'))openStationPicker();else if(b.hasAttribute('data-station-info'))window.ArrifyPlayer.actionDialog({title:'About your stations',description:'Choose from the channels tracked by xmplaylist. These are local-library rotations, not live SiriusXM streams. Missing songs enter the helper’s normal matching and acquisition process; availability, quality checks and download limits still apply. Your order and visibility are private to your account. Hiding or removing a station does not delete shared music or cancel work already queued.',confirmLabel:'Got it',onConfirm:async()=>{}});else if(b.dataset.stationAction)changeStation(b)});
document.addEventListener('change',event=>{if(event.target.matches('[data-station-action="hide"]'))changeStation(event.target)});

let radioSuggestionState=null,radioReview=null,radioPollTimer=null;
function radioBuildout(d){
 if(!d.sparse)return '<p class="muted">Refresh the mix to see the latest related songs.</p>';
 const count=(d.suggestions||[]).length;
 return '<div class="radio-buildout"><h2>Give this station more variety</h2><p>Only '+Number(d.total)+' related '+(Number(d.total)===1?'song is':'songs are')+' available right now. '+(count?'We found '+count+' promising '+(count===1?'addition.':'additions.')+' Review the albums, then choose which to request.':d.enriching?'Finding related recommendations. You can keep listening.':'Not enough confident recommendations yet. Try another song or artist, or refresh the mix later.')+'</p>'+(count?'<button id="radio-review" class="chip">Review '+count+' '+(count===1?'recommendation':'recommendations')+'</button>':'')+' <a class="text-button" href="#library/requests">Track music requests ↗</a><div id="radio-review-list"></div></div>';
}
function watchRadioSuggestions(snapshot,attempt=0){
 if(attempt>=12){const message=$('#radio-buildout p');if(radioSuggestionState===snapshot&&message)message.textContent='Recommendations are taking longer. Refresh the mix in a moment to check again.';return}radioPollTimer=setTimeout(async()=>{if(radioSuggestionState!==snapshot||!me)return;try{const d=await api('/radio/'+snapshot.kind+'/'+snapshot.seed+'?limit=1');if(radioSuggestionState!==snapshot)return;snapshot.items=d.suggestions||[];if(snapshot.noTracks&&(d.tracks?.length||!d.enriching))return render();if(!d.enriching||snapshot.items.length){$('#radio-buildout').innerHTML=radioBuildout(d)}else watchRadioSuggestions(snapshot,attempt+1)}catch{const message=$('#radio-buildout p');if(radioSuggestionState===snapshot&&message)message.textContent='Recommendations are temporarily unavailable. Refresh the mix to try again.'}},2500);
}
function paintRadioReview(review){
 if(radioReview!==review||!$('#radio-review-list'))return;
 const selected=review.items.filter(x=>x.status==='ready'&&x.selected).length,requestLabel=review.submitting?'Requesting…':review.preparing?'Verifying albums…':selected?'Request '+selected+' '+(selected===1?'album':'albums'):review.items.some(x=>x.status==='ready')?'Choose albums to request':review.items.some(x=>x.status==='requested')?'Requests complete':'No verified albums';
 $('#radio-review-list').innerHTML='<p class="radio-review-status" role="status">'+esc(review.message||'')+'</p><div class="radio-request-list">'+review.items.map((x,i)=>'<label class="radio-request-row"><input type="checkbox" data-radio-choice="'+i+'" '+(x.selected||x.status==='requested'?'checked':'')+' '+(x.status!=='ready'||review.preparing||review.submitting?'disabled':'')+'><span><strong>'+esc(x.item?.album||x.album||x.title)+'</strong><small>'+esc(x.item?.artist||x.artist)+' · '+esc(x.item?.title||x.title)+'</small><small class="'+(x.status==='requested'?'radio-requested':'')+'">'+esc(x.message||x.status)+'</small></span></label>').join('')+'</div><div class="detail-actions"><button id="radio-request-selected" class="primary" '+(!selected||review.preparing||review.submitting?'disabled':'')+'>'+requestLabel+'</button><a class="chip" href="#library/requests">View request progress</a></div>';
}
async function reviewRadioRequests(){
 const snapshot=radioSuggestionState,owner=me?.id;if(!snapshot||!snapshot.items.length||!owner)return;clearTimeout(radioPollTimer);$('#radio-review').disabled=true;
 const review=radioReview={items:snapshot.items.slice(0,20).map(x=>({...x,status:'checking',selected:false,message:'Checking the official album…'})),preparing:true,submitting:false};const albums=new Set();paintRadioReview(review);
 for(let i=0;i<review.items.length;i++){
  if(!me||me.id!==owner||radioReview!==review||radioSuggestionState!==snapshot)return;
  const row=review.items[i];review.message='Verifying albums '+(i+1)+' of '+review.items.length+'…';paintRadioReview(review);
  try{
   const result=await api('/radio/resolve/'+snapshot.kind+'/'+snapshot.seed+'/'+row.recording_id);
   if(!me||me.id!==owner||radioReview!==review)return;const item=result.item;
   if(!item?.requestable)throw Error(item?.reason||'No verified official album is available.');
   const album=(item.artist+' · '+item.album).normalize('NFKD').toLocaleLowerCase();row.item=item;
   if(item.requested){row.status='requested';row.selected=false;row.message='Requested';paintRadioReview(review);continue;}
   if(albums.has(album)){row.status='duplicate';row.message='Included in another recommended album.'}
   else{albums.add(album);row.status='ready';row.selected=true;row.message='Ready to request'}
  }catch(error){row.status='unavailable';row.message=error.message}
  paintRadioReview(review);
 }
 review.preparing=false;review.message='Choose the albums you want. Downloads start only when you press Request.';paintRadioReview(review);
}
async function requestRadioAlbums(){
 const review=radioReview;if(!review||review.preparing||review.submitting||!me)return;const owner=me.id,selected=review.items.filter(x=>x.status==='ready'&&x.selected);review.submitting=true;let done=0;
 for(const [index,row] of selected.entries()){
  if(!me||me.id!==owner)break;review.message='Requesting albums '+(index+1)+' of '+selected.length+'…';paintRadioReview(review);
  try{await api('/requests',{selection:row.item.selection});row.status='requested';row.selected=false;row.message='Requested · follow progress in Music requests';done++}
  catch(error){row.message=error.message+' Check Music requests before retrying.'}
  paintRadioReview(review);
 }
 review.submitting=false;review.message=done+' '+(done===1?'album requested.':'albums requested.')+' Follow progress in Music requests; we’ll notify you when music is ready.';paintRadioReview(review);
}
document.addEventListener('change',event=>{const b=event.target.closest('[data-radio-choice]');if(!b||!radioReview||radioReview.submitting)return;const item=radioReview.items[Number(b.dataset.radioChoice)];if(item?.status==='ready')item.selected=b.checked;const count=radioReview.items.filter(x=>x.status==='ready'&&x.selected).length,button=$('#radio-request-selected');button.textContent=count?'Request '+count+' '+(count===1?'album':'albums'):'Choose albums to request';button.disabled=!count||radioReview.preparing});

function radioResults(d){const seeds=[...d.artists.slice(0,2).map(x=>({kind:'artist',id:x.id,name:x.name,artwork:x.artwork})),...d.tracks.slice(0,2).map(x=>({kind:'track',id:x.id,name:x.title,artwork:x.artwork}))];return seeds.length?section('Stations','<div class="radio-results">'+seeds.map(x=>'<a class="radio-result" href="#radio/'+x.kind+'-'+esc(x.id)+'"><img src="'+esc(x.artwork)+'" alt="" loading="lazy"><span><strong>'+esc(x.name)+' Radio</strong><small>'+(x.kind==='artist'?'Artist':'Song')+' station · from your library</small></span><span aria-hidden="true">◉</span></a>').join('')+'</div>'):''}
