function moodView(collections,key=''){
 const available=new Map(collections.filter(x=>x.tracks>0&&x.slug!=='jazz-for-sleep').map(x=>[x.slug,x]));
 const groups=moodGroups.map(g=>({...g,items:g.slugs.map(s=>available.get(s)).filter(Boolean)})).filter(g=>g.items.length);
 const group=groups.find(g=>g.id===key);
 if(group)return tabs('moods')+'<a class="chip mood-back" href="#moods">← All moods</a><h1 class="page-title">'+esc(group.name)+'</h1><p class="section-description">'+esc(group.description)+'</p>'+cards(group.items,'collection');
 return tabs('moods')+'<h1 class="page-title">Moods</h1><p class="section-description">Find your mood. Make a little time for music.</p><div class="mood-hubs">'+groups.map(g=>'<a class="mood-hub" href="#moods/'+g.id+'" style="--mood-color:'+g.color+'">'+moodArtwork(g.id)+'<div class="mood-hub-copy"><h2>'+esc(g.name)+'</h2><p>'+esc(g.description)+'</p><span>'+g.items.length+' '+(g.items.length===1?'playlist':'playlists')+' <span aria-hidden="true">↗</span></span></div></a>').join('')+'</div>';
}
function tabs(selected='home'){return `<div class="tabs">${[['home','All'],['playlists','Playlists'],['moods','Moods'],['channels','Channels'],['albums','Albums'],['artists','Artists']].map(([key,label])=>`<a href="#${key}" class="chip ${selected===key?'selected':''}">${label}</a>`).join('')}</div>`}
function empty(title,text){return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(text)}</p></div>`}
function table(tracks,showPopularity=false){shownTracks=tracks;return `<table class="track-table ${showPopularity?'has-popularity':''}"><thead><tr><th>#</th><th>TITLE</th><th class="album-cell">ALBUM</th><th class="quality-cell">QUALITY</th>${showPopularity?`<th class="popularity-cell" scope="col" aria-sort="${context.popularitySorted?'descending':'none'}"><button type="button" id="artist-popularity-sort" aria-label="${context.popularitySorted?'Restore original song order':'Sort songs by popularity, highest first'}" title="${context.popularitySorted?'Restore original order':'Sort by popularity'}"><span class="doubloon-heading">Popularity</span><svg class="popularity-sort-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${context.popularitySorted?'<path d="M8 3v10m-4-4 4 4 4-4"/>':'<path d="m5 6 3-3 3 3m-6 4 3 3 3-3"/>'}</svg></button></th>`:''}<th></th></tr></thead><tbody>${tracks.map((t,i)=>`<tr data-track-row="${t.id}"><td class="track-index"><button data-play="${t.id}" aria-label="Play ${esc(t.title)}">${state?.current===t.id?'♫':i+1}</button></td><td><div class="track-main"><img src="${esc(t.artwork)}" loading="lazy" alt=""><div><a class="track-name" data-play="${t.id}">${esc(t.title)}</a><a class="track-artist" href="#artists/${t.artist_id}">${esc(t.artist)}</a></div></div></td><td class="album-cell"><a href="#albums/${t.album_id}">${esc(t.album)}</a></td><td class="quality-cell">${esc(t.quality)}</td>${showPopularity?`<td class="popularity-cell">${popularityLabel(t)}</td>`:''}<td class="track-actions"><button class="row-like ${liked.has(t.id)?'is-liked':''}" data-like="${t.id}" aria-pressed="${liked.has(t.id)}" aria-label="${liked.has(t.id)?'Remove from':'Add to'} Liked songs: ${esc(t.title)}" title="${liked.has(t.id)?'Remove from':'Add to'} Liked songs">${window.ArrifyPlayer.likeIcon(liked.has(t.id))}</button><button data-song-menu="${t.id}" aria-label="More options for ${esc(t.title)}" title="Song options" aria-haspopup="dialog">⋯</button></td></tr>`).join('')}</tbody></table>`}
function detailHeader(item,kind,count){return `<div class="detail-header"><div class="detail-cover">${art({...item,tracks:count},kind==='collection'?'collection':kind)}</div><div><span class="eyebrow">${esc(kind==='collection'?item.section:kind)}</span><h1>${esc(item.name)}</h1><p>${esc(item.description||item.artist||'From your library')}</p><small>${count.toLocaleString()} ${count===1?'song':'songs'}${item.year?' · '+esc(item.year):''}</small></div></div>`}
function playActions(count){return `<div class="detail-actions"><button id="play-all" class="primary" ${!count?'disabled':''}>▶ ${context.radio?'Play mix':context.channel?'Tune channel':'Play'}</button>${!context.channel&&count?'<button id="shuffle-all" class="chip">⤨ Shuffle</button>':''}${context.personal?.editable?'<button id="rename-playlist" class="chip">Rename</button><button id="playlist-visibility" class="chip visibility-toggle" aria-label="Share playlist with Arrify listeners" aria-pressed="'+(context.personal.visibility==='shared')+'" title="Toggle private or shared">'+(context.personal.visibility==='shared'?'Shared':'Private')+'</button><span class="playlist-delete-wrap"><button id="delete-playlist" class="chip" aria-expanded="false" aria-controls="playlist-delete-confirmation">Delete</button><span id="playlist-delete-confirmation" class="playlist-delete-confirmation" hidden role="group" aria-label="Confirm playlist deletion"><span>Delete playlist?</span><button id="playlist-delete-keep" class="chip">Keep</button><button id="playlist-delete-confirm" class="chip danger">Delete</button><span id="playlist-delete-error" role="status"></span></span></span>':''}</div>`}
