let browsePager=null;
function startBrowsePagination(epoch,view){
 const route=location.hash,uid=me?.id,grid=document.querySelector('#content .card-grid'),node=document.querySelector('#browse-more');if(!grid||!node)return null;
 let observer=null,busy=false,done=false,failed=false,disposed=false,offset=grid.children.length,frame=0;
 const seen=new Set(Array.from(grid.children,c=>c.dataset.go)),message=node.querySelector('span'),retry=node.querySelector('button');
 const valid=()=>!disposed&&epoch===requestEpoch&&route===location.hash&&uid===me?.id&&grid.isConnected&&node.isConnected;
 const dispose=()=>{disposed=true;observer?.disconnect();window.removeEventListener('scroll',check);window.removeEventListener('resize',check);cancelAnimationFrame(frame)};
 const check=()=>{if(frame)return;frame=requestAnimationFrame(()=>{frame=0;if(valid()&&!busy&&!failed&&!done&&node.getBoundingClientRect().top<innerHeight+600)load()})};
 async function load(manual=false){
  if(!valid()||busy||done||failed&&!manual)return;busy=true;failed=false;observer?.unobserve(node);retry.hidden=true;message.textContent='Loading more '+view+'…';node.setAttribute('aria-busy','true');
  try{
   const d=await api('/'+view+'?limit=60&offset='+offset);if(!valid())return;
   const holder=document.createElement('div');holder.innerHTML=cards(d.items,view);const fragment=document.createDocumentFragment();for(const card of Array.from(holder.firstElementChild.children)){if(seen.has(card.dataset.go))continue;seen.add(card.dataset.go);fragment.append(card)}grid.append(fragment);offset+=d.items.length;
   if(!d.items.length||offset>=d.total){done=true;observer?.disconnect();node.remove();return}message.textContent='More music loads as you scroll.';
  }catch(error){if(valid()){failed=true;message.textContent='Couldn’t load more '+view+'.';retry.hidden=false}}
  finally{busy=false;node.removeAttribute('aria-busy');if(valid()&&!done&&!failed){if(observer)observer.observe(node);else check()}}
 }
 retry.onclick=()=>load(true);
 if(typeof IntersectionObserver==='function'){observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))load()},{rootMargin:'0px 0px 600px 0px'});observer.observe(node)}else{window.addEventListener('scroll',check,{passive:true});window.addEventListener('resize',check,{passive:true});check()}
 return {dispose,load};
}
