    await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;controller.signal.addEventListener('abort',()=>reject(Error('Artwork timeout')),{once:true});if(controller.signal.aborted){reject(Error('Artwork cancelled'));return}image.src=objectURL});
