async function openProfile(){const profile=await api('/profile');me.text_size=profile.text_size||'standard';applyTextSize(me.text_size);$('#profile-display-name').value=profile.display_name;$('#profile-email').value=profile.email;$('#profile-text-size').value=profile.text_size||'standard';$('#profile-refresh').disabled=!profile.email;$('#profile-avatar').src=profile.avatar_url;$('#profile-avatar').hidden=false;$('#profile-message').textContent=profile.email?'':'Add your email to finish setting up your account.';$('#sound-leveling').value=soundPreferences.leveling;$('#sound-gapless').checked=soundPreferences.gapless;$('#sound-buffer').value=deviceBufferMode();$('#sound-gapless').disabled=!window.ArrifyGapless.supported();$('#sound-message').textContent='';me.playlist_shared_default=!!profile.playlist_shared_default;$('#profile-playlist-sharing').checked=me.playlist_shared_default;$('#profile-sharing-message').textContent='';$('#profile-name').textContent=profile.display_name;$('#profile-handle').textContent='@'+profile.username;$('#profile-dialog .account-edit').open=!!me.needs_email;accountSectionSerial++;accountRecent=null;accountSection('overview',false);$('#profile-insights').innerHTML='<p class="profile-help">Loading your listening…</p>';$('#profile-playlist-summary').innerHTML='';$('#profile-dialog').showModal();$('#profile-dialog').scrollTop=0;loadProfileInsights(profile.id);if(me.needs_email)accountSection('settings',false);window.ArrifyApple.renderProfile().catch(()=>{});window.ArrifySpotify?.renderProfile().catch(()=>{})}
let accountSectionSerial=0,accountRecent=[];
async function loadProfileInsights(uid){
 try{const stats=await api('/profile/stats');if(me?.id!==uid||!$('#profile-dialog').open)return;
 $('#profile-insights').innerHTML='<div class="account-section-heading"><h3>Your listening</h3><span>'+esc(stats.period)+'</span></div><div class="account-stat-grid"><div><span>Recorded plays</span><strong>'+Number(stats.starts).toLocaleString()+'</strong></div><div><span>Top artist</span><strong>'+esc(stats.top_artist||'Your next discovery')+'</strong></div></div><p class="account-stat-note">Private to you. Recorded plays count track starts.</p>';accountRecent=stats.recent;if($('#profile-dialog').dataset.accountSection==='recent')accountSection('recent',false);

 }catch{if(me?.id===uid&&$('#profile-dialog').open){accountRecent=false;$('#profile-insights').innerHTML='<p class="profile-help">Your listening summary is unavailable right now. You can still use your account settings.</p>';if($('#profile-dialog').dataset.accountSection==='recent')accountSection('recent',false)}}
}
$('#profile-playlist-sharing').addEventListener('change',async event=>{
 const input=event.target,uid=me?.id,previous=!!me?.playlist_shared_default,message=$('#profile-sharing-message');input.disabled=true;message.textContent='Saving…';
 try{const saved=await api('/profile/sharing',{playlist_shared_default:input.checked});if(me?.id!==uid)return;me.playlist_shared_default=!!saved.playlist_shared_default;input.checked=me.playlist_shared_default;message.textContent='New playlists default to '+(input.checked?'Shared.':'Private.')+' Existing playlists are unchanged.'}
 catch(error){if(me?.id===uid){input.checked=previous;message.textContent=error.message}}
 finally{if(me?.id===uid)input.disabled=false}
});
function paintAccountPlaylists(){
 $('#profile-playlist-summary').innerHTML='<div class="account-section-heading"><h3>Playlist sharing</h3><span>'+personal.filter(p=>p.visibility==='shared').length+' shared</span></div><p class="profile-help">Shared playlists are visible to other signed-in listeners. Open any playlist to change its privacy.</p>'+(personal.length?personal.map(p=>'<a class="account-playlist" href="#personal/'+p.id+'" data-profile-route><span>'+esc(p.name)+'</span><small>'+ (p.visibility==='shared'?'Shared':'Private')+'</small><span aria-hidden="true">›</span></a>').join(''):'<p class="profile-help">No playlists yet. Create one from Home or Your Library.</p>');
}
function accountSection(section,focus=true){
 const dialog=$('#profile-dialog'),titles={overview:'Your account',recent:'Recently played',playlists:'Your playlists',requests:'Music requests',settings:'Settings',services:'Music services'};if(!titles[section])return;
 if(section==='services'&&dialog.dataset.accountSection!=='services')dialog.dataset.servicesReturn=dialog.dataset.accountSection==='settings'?'settings':'overview';
 const serial=++accountSectionSerial,uid=me?.id;dialog.dataset.accountSection=section;$('#account-overview').hidden=section!=='overview';$('#account-playlists-panel').hidden=section!=='playlists';$('#account-settings-panel').hidden=section!=='settings';$('#account-services-panel').hidden=section!=='services';$('#account-section-content').hidden=!['recent','requests'].includes(section);$('#account-section-back').hidden=section==='overview';$('#profile-heading').textContent=titles[section];$('#profile-settings-toggle').setAttribute('aria-expanded',String(section==='settings'));$('.account-panel-body').scrollTop=0;if(focus)$('#profile-heading').focus({preventScroll:true});
 if(section==='playlists')paintAccountPlaylists();
 if(section==='settings')$('#profile-dialog .account-edit').open=true;
 if(section==='recent')$('#account-section-content').innerHTML='<p class="profile-help">Recent songs from Arrify and Apple Music. Only you can see this activity.</p>'+ (accountRecent===null?'<p role="status">Loading your recent songs…</p>':accountRecent===false?'<p role="status">Recent songs could not load.</p><button type="button" class="chip" data-account-recent-retry>Try again</button>':accountRecent.length?accountRecent.map(t=>'<div class="account-recent"><span><strong>'+esc(t.title)+'</strong><small>'+esc(t.artist)+'</small></span><small>'+ (t.source==='apple'?'Apple Music':'Arrify')+'</small></div>').join(''):'<p class="profile-help">Play a song to start your listening history.</p>')+'<a class="account-full-history" href="#history" data-profile-route>Open full Arrify history <span aria-hidden="true">›</span></a>';
 if(section==='requests'){const node=$('#account-section-content');node.innerHTML='<p class="profile-help" role="status">Loading your requests…</p>';api('/requests?limit=50').then(d=>{if(serial!==accountSectionSerial||uid!==me?.id||!dialog.open)return;paintAccountRequests(d)}).catch(()=>{if(serial===accountSectionSerial&&uid===me?.id&&dialog.open)node.innerHTML='<p role="status">Your requests could not load.</p><button type="button" class="chip" data-account-section="requests">Try again</button>'})}
}
function paintAccountRequests(d,append=false){const node=$('#account-section-content');if(!append)node.innerHTML='<div class="account-requests-intro"><p class="profile-help">Follow your requests from submission to ready to play.</p><button class="text-button" type="button" data-account-section="requests">Refresh</button></div>'+(d.status_unavailable?'<p role="status">Live status is unavailable. Showing saved progress.</p>':'')+'<div class="account-request-list"></div>';const list=node.querySelector('.account-request-list');list.insertAdjacentHTML('beforeend',d.items.length?d.items.map(requestCard).join(''):(append?'':'<p class="profile-help">No music requests yet. Find a missing song in Search to request it.</p>'));node.querySelector('[data-account-requests-more]')?.remove();if(d.next_offset<d.total)node.insertAdjacentHTML('beforeend','<button type="button" class="chip" data-account-requests-more="'+Number(d.next_offset)+'">More requests</button>')}
$('#profile-settings-toggle').addEventListener('click',()=>accountSection('settings'));
$('#account-section-back').addEventListener('click',()=>{const section=$('#profile-dialog').dataset.accountSection;if(section==='services'){const previous=$('#profile-dialog').dataset.servicesReturn||'overview';accountSection(previous,false);$('#'+(previous==='settings'?'account-settings-panel':'account-overview')+' [data-account-section=services]')?.focus();return}accountSection('overview',false);const target=section==='settings'?$('#profile-settings-toggle'):$('#profile-dialog [data-account-section="'+section+'"]');target?.focus()});
$('#profile-dialog').addEventListener('click',event=>{const route=event.target.closest('a[href^="#"]');if(route){$('#profile-dialog').close()}const b=event.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-account-recent-retry')){accountRecent=null;accountSection('recent');loadProfileInsights(me.id)}if(b.dataset.accountSection)accountSection(b.dataset.accountSection);if(b.hasAttribute('data-account-requests-more')){const serial=accountSectionSerial,uid=me?.id;b.disabled=true;api('/requests?limit=50&offset='+Number(b.dataset.accountRequestsMore)).then(d=>{if(serial===accountSectionSerial&&uid===me?.id&&$('#profile-dialog').open)paintAccountRequests(d,true)}).catch(()=>{if(b.isConnected){b.textContent='Could not load. Try again';b.disabled=false}})}if(b.dataset.requestPlay)$('#profile-dialog').close()});
$('#profile-dialog').addEventListener('close',()=>{accountSectionSerial++});

$('#profile-avatar').addEventListener('error',e=>e.target.hidden=true);
$('#profile-form').addEventListener('submit',async e=>{e.preventDefault();$('#profile-save').disabled=true;$('#profile-message').textContent='Saving…';try{const profile=await api('/profile',{display_name:$('#profile-display-name').value,email:$('#profile-email').value,text_size:$('#profile-text-size').value});me={...me,display_name:profile.display_name,avatar_url:profile.avatar_url,text_size:profile.text_size,needs_email:!profile.email};renderAccount();$('#profile-name').textContent=profile.display_name;$('#profile-avatar').src=profile.avatar_url;$('#profile-avatar').hidden=false;$('#profile-refresh').disabled=!profile.email;$('#profile-message').textContent='Profile saved.'}catch(error){$('#profile-message').textContent=error.message}finally{$('#profile-save').disabled=false}});

$('#profile-refresh').addEventListener('click',()=>safe(async()=>{const profile=await api('/profile/refresh',{});me.avatar_url=profile.avatar_url;renderAccount();$('#profile-avatar').src=profile.avatar_url;$('#profile-avatar').hidden=false;$('#profile-message').textContent='Photo refreshed.'}));

$('#profile-text-size').addEventListener('change',()=>applyTextSize($('#profile-text-size').value));
