let deletingUser=null;document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.userDetails){const panel=$('#user-details-'+b.dataset.userDetails);panel.hidden=!panel.hidden;b.setAttribute('aria-expanded',String(!panel.hidden));return}if(b.id==='admin-refresh-requests')safe(render);if(b.dataset.adminAction){const action=b.dataset.adminAction,id=Number(b.dataset.userId),username=b.dataset.username;if(action==='delete'){deletingUser={id,username};$('#admin-delete-name').textContent=username;$('#admin-delete-confirm').value='';$('#admin-delete-message').textContent='';$('#admin-delete-dialog').showModal();return}if(action==='freeze'){window.ArrifyPlayer.actionDialog({title:'Freeze account?',description:username+' will be unable to sign in or start new access. Existing downloads continue.',confirmLabel:'Freeze account',danger:true,onConfirm:async()=>{await api('/admin/users',{id,action});await refreshApprovals();await render()}});return}safe(async()=>{b.disabled=true;try{await api('/admin/users',{id,action});await refreshApprovals();await render()}finally{b.disabled=false}})}if(b.id==='admin-requests-more')safe(async()=>{b.disabled=true;try{const d=await api('/admin/requests?limit=50&offset='+b.dataset.offset);if(location.hash!=='#admin/requests')return;const list=$('#admin-request-list'),seen=new Set([...list.querySelectorAll('[data-admin-request]')].map(x=>x.dataset.adminRequest));list.insertAdjacentHTML('beforeend',d.items.filter(x=>!seen.has(x.user_id+':'+x.id)).map(adminRequestCard).join(''));if(d.next_offset>=d.total)b.remove();else b.dataset.offset=d.next_offset}finally{b.disabled=false}})});
$('#admin-delete-form').addEventListener('submit',e=>{e.preventDefault();if(!deletingUser)return;const u={...deletingUser};$('#admin-delete-submit').disabled=true;safe(async()=>{try{await api('/admin/users',{id:u.id,action:'delete',confirm_username:$('#admin-delete-confirm').value});$('#admin-delete-dialog').close();deletingUser=null;await refreshApprovals();await render()}catch(error){$('#admin-delete-message').textContent=error.message}finally{$('#admin-delete-submit').disabled=false}})});
let checkingSession=false;async function checkAccountAccess(){if(!me||checkingSession)return;checkingSession=true;try{await api('/me')}catch(error){if(error.status===401||error.status===403){playback.stop();for(const d of document.querySelectorAll('dialog[open]'))d.close();sessionStorage.setItem('arrify:access-ended','1');resetNavigation();location.reload()}}finally{checkingSession=false}}setInterval(()=>{if(me&&(!document.hidden||playback.intent))checkAccountAccess()},20000);window.addEventListener('focus',checkAccountAccess);

let folderPath='',folderParent=null,folderEpoch=0,folderFilterTimer=null;async function browseLibraryFolders(path=''){const epoch=++folderEpoch,filter=$('#library-folder-filter').value;$('#library-folder-message').textContent='Loading folders…';try{const d=await api('/admin/library/folders?path='+encodeURIComponent(path)+'&filter='+encodeURIComponent(filter));if(epoch!==folderEpoch||!$('#library-folder-dialog').open)return;folderPath=d.path;folderParent=d.parent;$('#library-folder-path').textContent=d.path||'Mapped music folders';$('#library-folder-up').disabled=d.parent===null;$('#library-folder-select').disabled=!d.path;$('#library-folder-list').innerHTML=d.items.map(x=>'<button type="button" class="folder-entry" data-folder-path="'+esc(x.path)+'">'+esc(x.name)+' <span aria-hidden="true">›</span></button>').join('')||'<p class="muted">No matching subfolders.</p>';$('#library-folder-message').textContent=d.has_more?'Showing the first 200 folders. Filter by name to narrow the list.':''}catch(error){if(epoch===folderEpoch)$('#library-folder-message').textContent=error.message}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='location-browse'){$('#library-folder-filter').value='';$('#library-folder-dialog').showModal();browseLibraryFolders($('#location-form').elements.path.value||'')}if(b.dataset.folderPath!==undefined){$('#library-folder-filter').value='';browseLibraryFolders(b.dataset.folderPath)}if(b.id==='library-folder-roots'){$('#library-folder-filter').value='';browseLibraryFolders('')}if(b.id==='library-folder-up'&&folderParent!==null){$('#library-folder-filter').value='';browseLibraryFolders(folderParent)}if(b.id==='library-folder-select'&&folderPath){const f=$('#location-form');f.elements.path.value=folderPath;if(!f.elements.name.value)f.elements.name.value=folderPath.split('/').filter(Boolean).pop();$('#library-folder-dialog').close();f.elements.name.focus()}});$('#library-folder-filter').addEventListener('input',()=>{clearTimeout(folderFilterTimer);folderFilterTimer=setTimeout(()=>browseLibraryFolders(folderPath),250)});

