 if(filter==='recent'){const d=await api('/history?limit=100');const tracks=d.items.map(x=>x.track);context={ids:tracks.map(t=>t.id)};return html+'<h2 class="library-filter-title">Recently played</h2>'+(tracks.length?table(tracks):empty('The needle’s up.','Your listening history appears here after you play a song.'))+'</div>'}
 if(filter==='albums'||filter==='artists'){const d=await api('/'+filter+'?limit=60');return html+'<p class="library-result-count">'+d.total.toLocaleString()+' '+filter+' in the collection</p>'+libraryRows(d.items,filter)+(d.total>60?'<button class="chip" data-library-more="'+filter+'" data-offset="60">Load more</button>':'')+'</div>'}
 await refreshPersonal();
 if(filter==='all')html+='<div class="library-shortcuts library-pinned"><a href="#library/liked"><span class="library-shortcut-icon" aria-hidden="true">'+window.ArrifyPlayer.likeIcon(true)+'</span><span><strong>Liked songs</strong><small>'+liked.size.toLocaleString()+(liked.size===1?' song':' songs')+'</small></span><span aria-hidden="true">›</span></a><a href="#requests"><span class="library-shortcut-icon history-icon" aria-hidden="true">↧</span><span><strong>Music requests</strong><small>Track progress and play new arrivals</small></span><span aria-hidden="true">›</span></a><a href="#party"><span class="library-shortcut-icon history-icon" aria-hidden="true">♫</span><span><strong>PartyQueue</strong><small>Host a party. Let everyone choose.</small></span><span aria-hidden="true">›</span></a></div>';
 if(filter!=='shared')html+=section('Your playlists',personal.length?libraryRows(personal,'personal'):empty('Every mix starts somewhere.','Create a playlist, then add songs from their … menu.'));
