document.addEventListener('click',e=>{if(!e.target.closest('#artist-popularity-sort')||!context.artistTracks)return;context.popularitySorted=!context.popularitySorted;const tracks=[...context.artistTracks];if(context.popularitySorted)tracks.sort((a,b)=>(b.popularity?.score??-1)-(a.popularity?.score??-1));context.ids=context.catalogAlbumIds||tracks.map(t=>t.id);const current=document.querySelector('#content .track-table');if(current){current.outerHTML=table(tracks,true);document.querySelector('#artist-popularity-sort')?.focus({preventScroll:true})}});

function pollArtistPopularity(key,epoch,delay=15000,view='artists'){clearTimeout(artistPopularityTimer);artistPopularityTimer=setTimeout(async()=>{if(epoch!==requestEpoch||location.hash!=='#'+view+'/'+key)return;try{const d=await api('/'+view+'/'+encodeURIComponent(key));if(epoch!==requestEpoch||location.hash!=='#'+view+'/'+key)return;context.artistTracks=d.tracks;const tracks=[...d.tracks];if(context.popularitySorted)tracks.sort((a,b)=>(b.popularity?.score??-1)-(a.popularity?.score??-1));context.ids=context.catalogAlbumIds||tracks.map(t=>t.id);const current=document.querySelector('#content .track-table');const focused=document.activeElement?.id==='artist-popularity-sort';if(current)current.outerHTML=table(tracks,true);if(focused)document.querySelector('#artist-popularity-sort')?.focus({preventScroll:true});const note=document.querySelector('.popularity-note');if(note)note.textContent='Tap Popularity to sort; tap the coins for sources. '+(d.popularity_pending?'Fetching popularity — ratings will appear automatically.':d.tracks.some(t=>t.popularity)?'1–3 coins reflect streaming reach, charts and airplay. Blank means below threshold or insufficient evidence.':'No reliable popularity data is available for these songs yet.');pollArtistPopularity(key,epoch,d.popularity_pending?15000:60000,view)}catch{if(epoch===requestEpoch)pollArtistPopularity(key,epoch,15000,view)}},delay)}

document.addEventListener('click',e=>{const button=e.target.closest('[data-popularity-track]');if(!button)return;const t=shownTracks.find(t=>t.id===Number(button.dataset.popularityTrack));if(!t?.popularity)return;let dialog=document.querySelector('#popularity-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='popularity-dialog';dialog.className='popularity-dialog';document.body.append(dialog);dialog.addEventListener('close',()=>{if(dialog.returnFocus?.isConnected)dialog.returnFocus.focus({preventScroll:true})})}dialog.returnFocus=button;const p=t.popularity;dialog.innerHTML=`<form method="dialog"><button class="popularity-close" aria-label="Close popularity details">×</button></form><h2 id="popularity-dialog-title">Popularity</h2><p class="popularity-song">${esc(t.title)} · ${esc(t.artist)}</p><p>${p.doubloons} of 3 coins</p><ul>${(p.evidence||[]).map(e=>`<li><strong>${esc(e.source)}</strong><span>${e.kind==='catalog_reach'?Number(e.total).toLocaleString()+' lifetime streams'+(e.daily!=null?' · '+Number(e.daily).toLocaleString()+' daily streams':''):e.kind==='historical'?'Historic peak #'+e.rank+' ('+e.year+') — established hit':e.kind==='catalog'?Number(e.value).toLocaleString()+' lifetime listens':e.kind==='satellite'?Number(e.value).toLocaleString()+' plays in '+esc(e.window)+' · station rank #'+e.rank:'Chart position #'+e.rank}${e.growth_pct?' · daily streams up '+e.growth_pct+'% versus '+esc(e.movement_period):e.rising?' · up '+e.rising+' positions since the '+esc(e.movement_period||'previous dated snapshot'):''}</span>${e.reported?'<small>Provider reporting date: '+esc(e.reported)+(Date.now()/1000-e.reported_ts>3*86400?' · daily count excluded as outdated':'')+'</small>':''}${e.published?'<small>Chart week: '+esc(e.published)+(e.stations?' · '+Number(e.stations)+' reporting stations':'')+'</small>':''}${e.updated?'<small>Checked '+new Date(e.updated*1000).toLocaleString()+(e.stale?' · cached, refresh delayed':'')+'</small>':''}${e.url?'<a href="'+esc(e.url)+'" target="_blank" rel="noopener noreferrer">View source</a>':''}</li>`).join('')}</ul><p class="popularity-footnote">Sources have different audiences. Coins summarize available evidence across artists; they are not measured market share. Radio coverage uses published Mediabase formats; satellite coverage uses monitored SiriusXM stations.</p>`;dialog.setAttribute('aria-labelledby','popularity-dialog-title');dialog.showModal()});

// Pointer handles keep ordinary list scrolling intact; arrow controls remain available.
let stationDrag=null;
document.addEventListener('pointerdown',event=>{
 const handle=event.target.closest('[data-station-drag]');if(!handle||stationSaving||event.button!==0)return;
 const row=handle.closest('[data-station-row]');stationDrag={handle,row,slug:handle.dataset.stationDrag,start:[...row.parentElement.children].indexOf(row)};
 handle.setPointerCapture(event.pointerId);row.classList.add('station-dragging');event.preventDefault();
});
document.addEventListener('pointermove',event=>{
 if(!stationDrag)return;const {row}=stationDrag,list=row.parentElement;
 const other=[...list.children].find(x=>{const b=x.getBoundingClientRect();return x!==row&&event.clientY>=b.top&&event.clientY<=b.bottom});
 if(other){const before=new Map([...list.children].map(x=>[x,x.getBoundingClientRect().top]));const b=other.getBoundingClientRect();list.insertBefore(row,event.clientY<b.top+b.height/2?other:other.nextSibling);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)for(const [x,top] of before){if(x!==row)x.animate([{transform:`translateY(${top-x.getBoundingClientRect().top}px)`},{transform:'translateY(0)'}],{duration:140,easing:'ease-out'});}}
 if(event.clientY<90)window.scrollBy(0,-16);else if(event.clientY>innerHeight-100)window.scrollBy(0,16);
});
async function finishStationDrag(cancel){
 const drag=stationDrag;if(!drag)return;stationDrag=null;drag.row.classList.remove('station-dragging');
 const target=[...drag.row.parentElement.children].indexOf(drag.row);
 if(cancel||target===drag.start){paintStations();return;}
 const button=drag.handle;button.dataset.stationAction='move';button.dataset.stationSlug=drag.slug;button.dataset.stationTarget=String(target);await changeStation(button);
}
document.addEventListener('pointerup',()=>finishStationDrag(false));
document.addEventListener('pointercancel',()=>finishStationDrag(true));

function acquisitionMarkup(d){
 const when=value=>value?new Date(typeof value==='number'?value*1000:value).toLocaleString():'Not reported';
 const phases={waiting:'Waiting for the next cycle',maintenance:'Checking acquisition and downloads',prepare:'Preparing verified albums',unknown:'No activity reported'};
 return `<section id="acquisition-panel"><div class="section-head"><h2>Acquisition</h2><button class="chip" id="acquisition-refresh">Refresh</button></div><p class="muted">${esc(phases[d.worker.phase]||d.worker.phase)} · ${esc(when(d.worker.updated))}</p>${d.worker.stale||d.unavailable?'<p role="status" class="admin-notice">Helper status is stale or unavailable. Counts may be out of date.</p>':''}<p class="muted">Discovery: ${esc(d.discovery?.status||'Not reported')}${d.discovery?.started?' · started '+esc(when(d.discovery.started)):''}</p><h3>Stations</h3><div class="acquisition-stations">${d.stations.map(s=>`<article class="acquisition-station"><h3>${esc(s.name)}</h3><p class="muted">${s.pending?'Waiting for first helper refresh':Number(s.observed)+' songs found · '+esc(when(s.updated))}</p><dl>${[['available','Available'],['awaiting_verification','Awaiting verification'],['verified','Verified'],['queued','Acquisition queued'],['downloaded','Downloaded'],['waiting','Waiting / review']].map(([key,label])=>`<div><dt>${label}</dt><dd>${Number(s.counts[key]||0)}</dd></div>`).join('')}</dl></article>`).join('')}</div><details class="admin-info"><summary>What these counts mean</summary><p>Queued means an acquisition or search request, not a confirmed active download. Downloaded songs may still need importing. Station counts are songs; acquisition and transfer counts below are shared records and can overlap across stations. Metadata verification, ownership, quality rules and download limits still apply.</p></details><h3>Shared acquisition records</h3><div class="acquisition-counts">${Object.entries(d.request_states).map(([state,count])=>`<span>${esc(state.replaceAll('-',' '))} <strong>${Number(count)}</strong></span>`).join('')}</div><h3>Transfer snapshot</h3><p class="muted">${esc(when(d.transfers_updated))}</p><div class="acquisition-counts">${Object.entries(d.transfers).map(([state,count])=>`<span>${esc(state.replaceAll('-',' '))} <strong>${Number(count)}</strong></span>`).join('')||'No transfer report yet.'}</div><h3>Recent decisions</h3>${d.recent.map(r=>`<article class="acquisition-decision"><strong>${esc(r.album||'Album')} · ${esc(r.artist||'Unknown artist')}</strong><p>${esc(r.reason)}</p><small class="muted">${esc(when(r.updated))}</small></article>`).join('')||'<p class="muted">No decisions reported yet.</p>'}<p class="muted">Refreshes every 20 seconds while this page is visible.</p><p id="acquisition-error" role="status"></p></section>`;
}
let acquisitionRefreshing=false;
async function refreshAcquisition(){if(acquisitionRefreshing||document.hidden||location.hash!=='#admin/acquisition')return;acquisitionRefreshing=true;try{const d=await api('/admin/acquisition');if(location.hash==='#admin/acquisition'){const panel=$('#acquisition-panel');const expanded=panel?.querySelector('details')?.open;if(panel){panel.outerHTML=acquisitionMarkup(d);if(expanded)$('#acquisition-panel details').open=true;}}}catch(e){const error=$('#acquisition-error');if(error)error.textContent='Could not refresh. Showing the last snapshot.';}finally{acquisitionRefreshing=false}}
setInterval(refreshAcquisition,20000);
document.addEventListener('click',e=>{if(e.target.closest('#acquisition-refresh'))refreshAcquisition()});

let catalogAlbumEpoch=0;
async function openCatalogAlbum(selection,trackId=null,groupId=null){
 const epoch=++catalogAlbumEpoch;let dialog=$('#catalog-album-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='catalog-album-dialog';dialog.setAttribute('aria-labelledby','catalog-album-title');document.body.append(dialog)}
 const trigger=document.activeElement;dialog.innerHTML='<form method="dialog"><button class="dialog-close" aria-label="Close album">×</button></form><h2 id="catalog-album-title">Album tracks</h2><div id="catalog-album-content" role="status">Loading album…</div>';
 dialog.onclose=()=>{catalogAlbumEpoch++;if(trigger?.isConnected)trigger.focus({preventScroll:true})};dialog.showModal();
 try{const d=await api('/discover/album?'+(groupId?'group='+encodeURIComponent(groupId):trackId?'track='+Number(trackId):'selection='+encodeURIComponent(selection)));if(epoch!==catalogAlbumEpoch||!dialog.open)return;$('#catalog-album-title').textContent=d.album.name;$('#catalog-album-content').innerHTML='<p class="muted">'+esc(d.album.artist)+(d.album.year?' · '+esc(d.album.year):'')+'</p><p class="muted">Official release · '+esc(d.album.edition)+'</p><div class="catalog-album-tracks">'+catalogAlbumRows(d.items)+'</div>';}
 catch(error){if(epoch===catalogAlbumEpoch&&dialog.open)$('#catalog-album-content').textContent=error.message;}
}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.catalogAlbum){event.preventDefault();openCatalogAlbum(button.dataset.catalogAlbum)}else if(button.dataset.albumPlay){safe(async()=>{selectionTrigger=button;if(!window.ArrifyApple?.isActive()&&!window.ArrifySpotify?.isActive()&&(!remoteListening()||!listeningOnline()))nativePlayback.prime();const ids=[...new Set([...button.closest('.catalog-album-tracks').querySelectorAll('[data-album-play]')].map(b=>Number(b.dataset.albumPlay)))];await command({action:'play',ids,track_id:Number(button.dataset.albumPlay)},true);$('#catalog-album-dialog')?.close()})}});

async function loadPublishedAlbum(epoch){
 const panel=$('#published-album');if(!panel)return;const track=Number(panel.dataset.track);panel.setAttribute('aria-busy','true');
 try{const d=await api('/discover/album?track='+track);if(epoch!==requestEpoch||!panel.isConnected)return;
 panel.innerHTML='<h2>'+esc(d.album.name)+(d.album.year?' · '+esc(d.album.year):'')+'</h2><p class="muted">Published album track list · '+esc(d.album.artist)+'</p><div class="catalog-album-tracks">'+catalogAlbumRows(d.items)+'</div>';$('#album-local-copies').open=false;context.ids=[...new Set(d.items.map(x=>x.local_track_id).filter(Boolean))];context.catalogAlbumIds=context.ids;const header=$('#content .detail-header');if(header){header.querySelector('h1').textContent=d.album.name;header.querySelector('p').textContent=d.album.artist;header.querySelector('small').textContent=d.items.length+' tracks · '+d.items.filter(x=>x.local_track_id).length+' available'+(d.album.year?' · '+d.album.year:'');}for(const el of document.querySelectorAll('#content .popularity-note,#content .popularity-explainer'))el.hidden=true;
 }catch(error){if(epoch===requestEpoch&&panel.isConnected){panel.innerHTML='<p class="muted">The published track list could not be verified. Your local songs are shown below.</p><button class="chip" data-album-retry>Retry album lookup</button>';}}
 finally{panel.removeAttribute('aria-busy')}
}
document.addEventListener('click',event=>{if(event.target.closest('[data-album-retry]'))loadPublishedAlbum(requestEpoch)});

function catalogAlbumRows(items){const missing=new Set(items.filter(x=>!x.local_track_id&&!x.requested&&x.selection).map(x=>x.selection)).size;return '<div class="album-request-actions"><button class="chip primary" data-album-request-all '+(!missing?'disabled':'')+' aria-label="Request all missing songs from this album">'+(missing?'Add all missing · '+missing:'All songs available or requested')+'</button><span class="muted" data-album-request-status role="status" aria-live="polite"></span></div>'+items.map(x=>'<div class="catalog-album-track '+(x.local_track_id?'is-available':'is-unavailable')+'"><span class="album-track-number">'+(x.disc>1?Number(x.disc)+'.':'')+esc(x.number)+'</span>'+(x.local_track_id?'<button class="album-track-select" data-album-play="'+Number(x.local_track_id)+'" aria-label="Play '+esc(x.title)+'"><strong>'+esc(x.title)+'</strong><small>'+esc(x.artist)+'</small></button><span class="album-track-quality">'+esc(x.local_quality||'Available')+'</span>':'<div class="album-track-missing"><strong>'+esc(x.title)+'</strong><small>'+esc(x.artist)+'</small></div><button class="chip" data-request="'+esc(x.selection)+'" '+(x.requested?'disabled':'')+' aria-label="Request '+esc(x.title)+'">'+(x.requested?'Requested':'Request')+'</button>')+'</div>').join('')}

function artistAlbumRow(x){return '<button class="discography-album artist-album-row" data-discography-group="'+esc(x.group_id)+'" data-release-year="'+esc(x.year||'')+'"><img src="/api/v1/catalog-artwork/'+encodeURIComponent(x.group_id)+'" alt="" width="56" height="56" loading="lazy" decoding="async"><span class="artist-album-copy"><strong>'+esc(x.title)+'</strong><small>'+esc([x.year,...(x.types||[])].filter(Boolean).join(' · ')||'Album')+'</small></span><span class="artist-album-chevron" aria-hidden="true">›</span></button>'}

async function loadArtistAlbums(offset=0,epoch=requestEpoch){
 const panel=$('#artist-discography');if(!panel||panel.dataset.loading==='true')return;const button=panel.querySelector('[data-discography-more]');panel.dataset.loading='true';panel.setAttribute('aria-busy','true');button.disabled=true;button.textContent='Loading albums…';
 try{const d=await api('/discover/artist-albums?'+(panel.dataset.mbid?'mbid='+encodeURIComponent(panel.dataset.mbid):'artist='+encodeURIComponent(panel.dataset.artist))+'&offset='+offset);if(epoch!==requestEpoch||!panel.isConnected)return;
 panel.querySelector('.discography-list').insertAdjacentHTML('beforeend',d.items.map(artistAlbumRow).join(''));
 panel.dataset.loaded='true';panel.dataset.next=d.next_offset??'';sortArtistAlbums(panel);button.hidden=d.next_offset===null;button.dataset.offset=d.next_offset??0;button.textContent='More albums';if(!d.items.length&&offset===0)button.textContent='No catalog albums found';
 }catch(error){if(panel.isConnected){button.textContent='Retry album lookup';button.title=error.message;button.dataset.offset=offset;}}
 finally{panel.dataset.loading='false';panel.removeAttribute('aria-busy');button.disabled=false;if(panel.dataset.tabbed==='true'&&!panel.hidden&&panel.dataset.next&&button.textContent==='More albums')setTimeout(()=>{if(panel.isConnected&&epoch===requestEpoch&&!panel.hidden)loadArtistAlbums(Number(panel.dataset.next),epoch)},0);}
}
document.addEventListener('click',event=>{const group=event.target.closest('[data-discography-group]');if(group)openCatalogAlbum(null,null,group.dataset.discographyGroup);const more=event.target.closest('[data-discography-more]');if(more)loadArtistAlbums(Number(more.dataset.offset||0));});

async function searchCatalogAlbums(button){
 const panel=$('#catalog-explore'),query=$('#search').value.trim(),epoch=requestEpoch,offset=Number(button.dataset.offset||0);button.disabled=true;button.textContent='Searching…';
 try{const d=await api('/discover/explore?q='+encodeURIComponent(query)+'&offset='+offset);if(epoch!==requestEpoch||!panel.isConnected)return;
 panel.querySelector('.explore-results').insertAdjacentHTML('beforeend',(d.artists||[]).map(a=>'<button class="discography-album" data-explore-artist="'+esc(a.id)+'" data-artist-name="'+esc(a.name)+'"><span>'+esc(a.name)+'</span><small>Artist'+(a.description?' · '+esc(a.description):'')+'</small></button>').join('')+d.items.filter(x=>![...panel.querySelectorAll('[data-discography-group]')].some(b=>b.dataset.discographyGroup===x.group_id)).map(x=>'<button class="discography-album" data-discography-group="'+esc(x.group_id)+'" data-release-year="'+esc(x.year||'')+'"><span>'+esc(x.title)+'</span><small>'+esc(x.artist)+' · '+esc(x.year||'Album')+'</small></button>').join(''));
 panel.append(button);button.dataset.offset=d.next_offset??0;button.hidden=d.next_offset===null;button.textContent='More albums';if(!d.items.length&&!d.artists?.length)panel.querySelector('.explore-results').textContent='No catalog matches. Try another artist or album name.';
 }catch(error){button.textContent='Retry catalog search';button.title=error.message;}finally{button.disabled=false;}
}
document.addEventListener('click',event=>{const search=event.target.closest('[data-explore-search]');if(search)searchCatalogAlbums(search);const artist=event.target.closest('[data-explore-artist]');if(artist){let dialog=$('#artist-catalog-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='artist-catalog-dialog';document.body.append(dialog)}dialog.innerHTML='<form method="dialog"><button class="dialog-close" aria-label="Close artist">×</button></form><h2>'+esc(artist.dataset.artistName)+'</h2><section id="artist-discography" data-mbid="'+esc(artist.dataset.exploreArtist)+'"><div class="discography-list"></div><button class="chip" data-discography-more>Explore albums</button></section>';dialog.onclose=()=>{dialog.replaceChildren();artist.focus({preventScroll:true})};dialog.showModal();loadArtistAlbums();}});

async function requestAlbumMissing(button){
 const panel=button.closest('.catalog-album-tracks');if(!panel||button.disabled||panel.dataset.requesting==='true')return;
 const rows=[...panel.querySelectorAll('button[data-request]')].filter(b=>!b.disabled),selections=[...new Set(rows.map(b=>b.dataset.request))];
 const status=panel.querySelector('[data-album-request-status]');if(!selections.length){button.disabled=true;button.textContent='All songs available or requested';return;}
 panel.dataset.requesting='true';button.disabled=true;button.setAttribute('aria-busy','true');rows.forEach(b=>b.disabled=true);let completed=0,error=null;
 try{for(const selection of selections){button.textContent='Adding '+(completed+1)+' of '+selections.length+'…';status.textContent=completed+' of '+selections.length+' requested';await api('/requests',{selection});completed++;for(const row of rows.filter(b=>b.dataset.request===selection)){row.textContent='Requested';row.dataset.albumBatchComplete='true';}}}
 catch(e){error=e;}
 finally{for(const row of rows){if(row.dataset.albumBatchComplete==='true')delete row.dataset.albumBatchComplete;else row.disabled=false;}panel.dataset.requesting='false';button.removeAttribute('aria-busy');button.disabled=!error;button.textContent=error?'Retry remaining · '+(selections.length-completed):'All missing songs requested';status.textContent=error?completed+' of '+selections.length+' requested. '+error.message:completed+' songs requested. Follow progress in Music requests.';if(!panel.isConnected)toast(error?completed+' songs requested. Reopen the album to request the rest.':completed+' songs requested. Follow progress in Music requests.');}
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-album-request-all]');if(button)requestAlbumMissing(button)});

function syncAlbumRequestAll(panel){if(!panel||panel.dataset.requesting==='true')return;const button=panel.querySelector('[data-album-request-all]');if(!button)return;const count=new Set([...panel.querySelectorAll('button[data-request]:not(:disabled)')].map(b=>b.dataset.request)).size;button.disabled=!count;button.textContent=count?'Add all missing · '+count:'All songs available or requested';}

let catalogDiscoveryTimer=null;
function scheduleCatalogDiscovery(epoch){
 clearTimeout(catalogDiscoveryTimer);const section=$('#catalog-section'),heading=$('.search-heading');if(!section||!heading)return;
 if(!context.hasLocalSearchResults)heading.insertAdjacentElement('afterend',section);
 const button=section.querySelector('[data-explore-search]');if(!button||!section.open||section.querySelector('.explore-results')?.children.length)return;
 catalogDiscoveryTimer=setTimeout(()=>{if(epoch===requestEpoch&&section.isConnected&&section.open&&location.hash==='#search'&&!button.disabled&&!button.hidden)searchCatalogAlbums(button)},600);
}
document.addEventListener('toggle',event=>{if(event.target.id==='catalog-section')scheduleCatalogDiscovery(requestEpoch)},true);

function setupArtistTabs(epoch){
 const albums=$('#artist-discography');if(!albums)return;albums.dataset.tabbed='true';albums.hidden=true;albums.setAttribute('role','tabpanel');albums.setAttribute('aria-labelledby','artist-tab-albums');
 const songs=document.createElement('section');songs.id='artist-songs-panel';songs.setAttribute('role','tabpanel');songs.setAttribute('aria-labelledby','artist-tab-songs');
 for(const el of [...content.querySelectorAll('.popularity-note,.popularity-explainer,.track-table')])songs.append(el);
 const nav=document.createElement('div');nav.className='artist-content-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','Artist music');nav.innerHTML='<button id="artist-tab-songs" role="tab" aria-selected="true" aria-controls="artist-songs-panel" tabindex="0" data-artist-tab="songs">Songs</button><button id="artist-tab-albums" role="tab" aria-selected="false" aria-controls="artist-discography" tabindex="-1" data-artist-tab="albums">Albums</button>';
 albums.before(nav,songs);albums.querySelector('h2')?.remove();albums.insertAdjacentHTML('afterbegin','<div class="artist-album-toolbar"><label>Release date <select data-artist-album-sort aria-label="Sort albums by release date"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label><span class="muted" data-album-count role="status">Full catalog · includes albums outside your library</span></div>');
 nav.addEventListener('click',event=>{const tab=event.target.closest('[data-artist-tab]');if(!tab)return;const showAlbums=tab.dataset.artistTab==='albums';for(const b of nav.querySelectorAll('[role=tab]')){const selected=b===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;}songs.hidden=showAlbums;albums.hidden=!showAlbums;if(showAlbums&&(!albums.dataset.loaded||albums.dataset.next))loadArtistAlbums(Number(albums.dataset.next||0),epoch);});
 nav.addEventListener('keydown',event=>{const tabs=[...nav.querySelectorAll('[role=tab]')],i=tabs.indexOf(document.activeElement);if(i<0)return;let n;if(event.key==='ArrowRight')n=(i+1)%tabs.length;else if(event.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(event.key==='Home')n=0;else if(event.key==='End')n=tabs.length-1;else return;event.preventDefault();tabs[n].focus();});
}
function sortArtistAlbums(panel){
 const select=panel.querySelector('[data-artist-album-sort]');if(!select)return;const list=panel.querySelector('.discography-list'),rows=[...list.children],direction=select.value==='oldest'?1:-1;
 rows.sort((a,b)=>{const ay=Number(a.dataset.releaseYear)||0,by=Number(b.dataset.releaseYear)||0;return (!ay)-(!by)||(ay-by)*direction||a.textContent.localeCompare(b.textContent)});for(const row of rows)list.append(row);
 const count=panel.querySelector('[data-album-count]');if(count)count.textContent=rows.length+' albums'+(panel.dataset.next?' loaded · fetching remaining albums…':' · catalog releases');
}
document.addEventListener('change',event=>{if(event.target.matches('[data-artist-album-sort]'))sortArtistAlbums(event.target.closest('#artist-discography'))});

document.addEventListener('submit',async event=>{
 if(event.target.id!=='branding-form')return;event.preventDefault();const form=event.target,status=form.querySelector('#branding-status'),buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
 try{status.textContent='Uploading…';const image=await ArrifyBranding.encode(form.querySelector('input').files[0]);const value=await api('/admin/branding',{action:'upload',image});ArrifyBranding.apply(value);document.querySelector('.branding-preview').src=value.icon_url;status.textContent='Server icon saved.';form.reset()}
 catch(error){status.textContent=error.message}finally{buttons.forEach(b=>b.disabled=false)}
});
document.addEventListener('click',async event=>{
 const button=event.target.closest('#branding-reset');if(!button)return;button.disabled=true;const status=document.querySelector('#branding-status');
 try{const value=await api('/admin/branding',{action:'reset'});ArrifyBranding.apply(value);document.querySelector('.branding-preview').src=value.icon_url;status.textContent='Default icon restored.'}catch(error){status.textContent=error.message;button.disabled=false}
});

$('#delete-my-account').onclick=()=>$('#delete-account-dialog').showModal();
$('#delete-account-cancel').onclick=()=>{$('#delete-account-dialog').close();$('#delete-account-password').value=''};
$('#delete-account-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('/account/delete',{password:$('#delete-account-password').value,confirm:$('#delete-account-confirm').checked});$('#delete-account-password').value='';location.replace('/')}catch(error){$('#delete-account-message').textContent=error.message}finally{button.disabled=false}};
